    localparam integer NVW = $clog2(W) + 1;
    initial if (K % (8 * W) != 0 || R > 16) $fatal(1, "K must be a multiple of 2,048, <= 32,768");

    // ------------------------------------------------------------------ synced reset
    wire [1:0] rn;
    ot_rst_relay #(.REGIONS(2)) u_rst (.clk(clk), .rst_n_in(rst_n), .rst_n(rn));
    wire rst_c = rn[0];

    // ------------------------------------------------------------------ pin registers
